/* Responsive, public sales catalog; never reads or writes workspace records. */
(function(root){
 'use strict';const catalog=root.YolkBrandLinks.catalog,escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),element=id=>document.getElementById(id);
 let lang=new URL(root.location.href).searchParams.get('lang')==='en'?'en':'th',query='';
 const t=(th,en)=>lang==='en'?en:th,n=value=>new Intl.NumberFormat(lang==='en'?'en-GB':'th-TH').format(value);
 function render(){document.documentElement.lang=lang;document.title=t('Demo ของแต่ละแบรนด์','Brand demo links')+' · CityMETER: Yolk';element('brand-catalog-language').textContent=lang==='th'?'English':'ไทย';element('brand-catalog-title').textContent=t('Demo ของแต่ละแบรนด์','Brand demo links');element('brand-catalog-intro').textContent=t('ส่งลิงก์ให้ลูกค้าลอง Yolk ด้วยแบรนด์และ format สำคัญของเขา หน้าแรกคือ “โอกาสขยาย”','Send a prospect a demo with their own brand and important format selected. It opens on Expansion opportunities.');element('brand-catalog-policy').textContent=t('ลิงก์ไม่ส่งข้อมูลงานของคุณ เกณฑ์/ร่างที่ผู้รับเคยบันทึกไว้จะคงเดิม; ผู้รับใหม่เริ่มจาก preset ของแบรนด์','Links contain no workspace data. A recipient’s saved criteria and drafts are retained; new recipients start from the brand preset.');element('brand-catalog-search-label').textContent=t('ค้นหาแบรนด์','Find a brand');element('brand-catalog-json').textContent=t('ดาวน์โหลด JSON','Download JSON');element('brand-catalog-limit').textContent=t('Snapshot CityMETER: บัญชีต้นทางและพิกัดไม่ยืนยันเปิดบริการ ผลิตภัณฑ์ทุกสาขา ลูกค้าจริง หรือผลธุรกิจ ตัวเลข preset เป็นสมมติฐาน Yolk ที่ปรับได้','CityMETER snapshot: source inventory and coordinates do not verify current operations, every branch offering, actual customers or business outcomes. Numeric presets are adjustable Yolk hypotheses.');element('brand-catalog-return').textContent=t('เปิด Yolk','Open Yolk');
  const rows=catalog.brands.filter(b=>[b.slug,b.brandId,b.name.th,b.name.en].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  element('brand-catalog-status').textContent=n(rows.length)+t(' แบรนด์มีข้อมูลในต้นทาง',' source-supported brands');
  element('brand-catalog-list').innerHTML=[['fuel','สถานีบริการน้ำมัน','Fuel'],['grocery','ร้านค้าของกินของใช้','Grocery'],['nonbank','Non-bank · 10 รายแรกใน source','Non-bank · First 10 source companies']].map(([industry,th,en])=>{const brands=rows.filter(b=>b.industryId===industry);if(!brands.length)return '';return `<section aria-labelledby="catalog-${industry}"><h2 id="catalog-${industry}">${escape(t(th,en))}</h2><div class="brand-catalog-grid">${brands.map(b=>{const url=root.YolkBrandLinks.urlFor(b.brandId,{lang});return `<article class="brand-catalog-card"><h3>${escape(b.name[lang])}</h3><small>${escape(b.scopeLabel[lang])}</small><p>${t('ยอดต้นทางใน scope','Source inventory in scope')}: <strong>${n(b.sourceDefaultScopeCount)}</strong> · ${t('พิกัดที่ใช้ได้','Valid coordinates')}: <strong>${n(b.defaultScopeValidCoordinates)}</strong></p><details><summary>${t('ที่มาและข้อจำกัด','Sources and limits')}</summary><p>${escape(b.sourceLimits[lang])}</p><small>${t('บันทึก snapshot','Snapshot captured')}: ${escape(b.sourceSnapshotCapturedAt)} · ${escape(b.brandId)}</small></details><label for="link-${escape(b.slug)}"><span>${t('ลิงก์ Demo','Demo link')}</span><input id="link-${escape(b.slug)}" readonly value="${escape(url)}"></label><div class="catalog-card-actions"><a class="btn secondary" href="${escape(url)}">${t('ทดลองใช้','Try demo')}</a><button type="button" class="quiet-link" data-brand-demo-copy="${escape(b.brandId)}" data-brand-catalog-copy>${t('คัดลอกลิงก์','Copy link')}</button></div></article>`}).join('')}</div></section>`}).join('')||'<p>'+t('ไม่พบแบรนด์ที่ค้นหา','No matching brand')+'</p>';
 }
 element('brand-catalog-language').addEventListener('click',()=>{lang=lang==='th'?'en':'th';render()});element('brand-catalog-search').addEventListener('input',event=>{query=event.target.value.trim();render()});render();
})(window);
